import { defineComponent, type PropType } from 'ui.vue3';

import { type TableBlockType } from 'im.v2.const';
import { Parser } from 'im.v2.lib.parser';

import { BuilderTextContent } from '../../builder-text-content/builder-text-content';
import { SourceHandler } from '../../source-handler/source-handler';
import { BaseBlock } from '../base/base';

import './table.css';

// @vue/component
export const TableBlock = defineComponent({
	name: 'TableBlock',
	components: { BaseBlock, BuilderTextContent, SourceHandler },
	props: {
		message: {
			type: Object,
			required: true,
		},
		block: {
			type: Object as PropType<TableBlockType>,
			required: true,
		},
		dialogId: {
			type: String,
			required: true,
		},
	},
	setup(): { naturalWidth: number; resizeObserver: ResizeObserver | null }
	{
		return {
			naturalWidth: 0,
			resizeObserver: null,
		};
	},
	data(): { isNarrow: boolean }
	{
		return {
			isNarrow: false,
		};
	},
	computed: {
		tableBlock(): TableBlockType
		{
			return this.block;
		},
		columnCount(): number
		{
			return this.tableBlock.rows[0].length ?? 1;
		},
	},
	mounted()
	{
		this.naturalWidth = this.measureNaturalWidth();
		this.initResizeObserver();
	},
	beforeUnmount()
	{
		this.resizeObserver!.disconnect();
	},
	methods: {
		initResizeObserver()
		{
			this.resizeObserver = new ResizeObserver(([entry]) => {
				this.isNarrow = entry.contentRect.width < this.naturalWidth;
			});
			this.resizeObserver.observe((this.$refs.container as HTMLElement).closest('.bx-im-message-base__wrap')!);
		},
		measureNaturalWidth(): number
		{
			const COLUMN_GAP = 10;
			const tbody = (this.$refs.container as HTMLElement).querySelector('tbody');
			const gridTemplateColumns = getComputedStyle(tbody!).gridTemplateColumns.split(' ');
			const [firstColumn, secondColumn] = gridTemplateColumns.map((element) => {
				return parseFloat(element);
			});

			if (secondColumn)
			{
				return firstColumn + secondColumn + COLUMN_GAP;
			}

			return firstColumn;
		},
		getFormattedText(text: string): string
		{
			return Parser.decodeInlineText(text);
		},
	},
	template: `
		<BaseBlock
			:message="message"
			:block="tableBlock"
			:dialogId="dialogId"
		>
			<SourceHandler :block="block" :messageId="message.id">
				<div
					:class="{ '--narrow': isNarrow }"
					:style="{ '--im-message-builder-table-cols': columnCount }"
					ref="container"
					class="bx-im-message-block-table__container"
					data-testid="message-builder-table"
				>
					<table class="bx-im-message-block-table__table">
						<tbody>
							<tr
								v-for="(row, rowIndex) in tableBlock.rows"
								:key="rowIndex"
							>
								<td
									v-for="(cell, cellIndex) in row"
									:key="cellIndex"
									data-testid="message-builder-table-cell"
								>
									<BuilderTextContent
										:text="getFormattedText(cell.text)"
										class="--line-clamp-3"
									/>
								</td>
							</tr>
						</tbody>
					</table>
				</div>
			</SourceHandler>
		</BaseBlock>
	`,
});
