import { defineComponent } from 'ui.vue3';

import { Utils } from 'im.v2.lib.utils';

import { SourcePopup, type SourceItem } from './source-popup';

const HIDE_DELAY = 100;

// @vue/component
export const SourceHandler = defineComponent({
	name: 'SourceHandler',
	components: { SourcePopup } as { SourcePopup: typeof SourcePopup },
	props: {
		block: {
			type: Object,
			required: true,
		},
		messageId: {
			type: Number,
			required: true,
		},
	},
	setup(): { hideTimeout: number }
	{
		return {
			hideTimeout: 0,
		};
	},
	data(): { showPopup: boolean; currentSource: SourceItem | null; bindElement: Element | null }
	{
		return {
			showPopup: false,
			currentSource: null,
			bindElement: null,
		};
	},
	computed: {
		popupId(): string
		{
			const uuid = Utils.text.getUuidV4();

			return `im-source-popup-${uuid}`;
		},
	},
	methods: {
		onClick(event: PointerEvent)
		{
			const sourceElement = (event.target as HTMLElement).closest('[data-source-id]');
			if (!sourceElement)
			{
				return;
			}

			const source = this.getSourceForId((sourceElement as HTMLElement).dataset.sourceId as string);
			if (!source)
			{
				return;
			}

			const isUrl = Utils.text.checkUrl(source.url);
			if (!isUrl)
			{
				return;
			}

			Utils.browser.openLink(source.url);
		},
		onMouseOver(event: MouseEvent)
		{
			const sourceElement = (event.target as HTMLElement).closest('[data-source-id]');
			if (!sourceElement)
			{
				this.startHideTimer();

				return;
			}

			const hasActivePopupForElement = this.bindElement === sourceElement && this.showPopup;
			if (hasActivePopupForElement)
			{
				this.clearHideTimer();

				return;
			}

			const source = this.getSourceForId((sourceElement as HTMLElement).dataset.sourceId as string);
			if (!source)
			{
				return;
			}

			this.clearHideTimer();
			this.showPopup = false;
			this.currentSource = source;
			this.bindElement = sourceElement;
			void this.$nextTick(() => {
				this.showPopup = true;
			});
		},
		onMouseLeave()
		{
			this.startHideTimer();
		},
		onPopupMouseEnter()
		{
			this.clearHideTimer();
		},
		startHideTimer()
		{
			clearTimeout(this.hideTimeout);
			this.hideTimeout = setTimeout(() => {
				this.showPopup = false;
			}, HIDE_DELAY);
		},
		clearHideTimer()
		{
			clearTimeout(this.hideTimeout);
		},
		getSourceForId(sourceId: string): SourceItem | null | undefined
		{
			const blockSources = this.block.sources ?? {};
			const rawSource = blockSources[sourceId];
			if (!rawSource)
			{
				return null;
			}

			return rawSource;
		},
	},
	template: `
		<div @click="onClick" @mouseover="onMouseOver" @mouseleave="onMouseLeave">
			<slot></slot>
		</div>
		<SourcePopup
			v-if="showPopup"
			:id="popupId"
			:source="currentSource"
			:bindElement="bindElement"
			@close="showPopup = false"
			@mouseEnter="onPopupMouseEnter"
			@mouseLeave="onMouseLeave"
		/>
	`,
});
