import { Type } from 'main.core';
import { BIcon, Outline as OutlineIcons } from 'ui.icon-set.api.vue';
import { defineComponent, type PropType } from 'ui.vue3';

import { Utils } from 'im.v2.lib.utils';
import { type MapBlockType } from 'im.v2.const';

import { BaseBlock } from '../base/base';

import './map.css';

// @vue/component
export const MapBlock = defineComponent({
	name: 'MapBlock',
	components: { BaseBlock, BIcon } as { BaseBlock: typeof BaseBlock, BIcon: typeof BIcon },
	props: {
		message: {
			type: Object,
			required: true,
		},
		block: {
			type: Object as PropType<MapBlockType>,
			required: true,
		},
		dialogId: {
			type: String,
			required: true,
		},
	},
	computed: {
		OutlineIcons(): typeof OutlineIcons
		{
			return OutlineIcons;
		},
		mapBlock(): MapBlockType
		{
			return this.block;
		},
		hasStatus(): boolean
		{
			return Type.isStringFilled(this.mapBlock.status);
		},
		hasText(): boolean
		{
			return Type.isStringFilled(this.mapBlock.text);
		},
		imageSource(): string
		{
			const isImage = Utils.text.isUrlImageLike(this.mapBlock.imageUrl);
			if (!isImage)
			{
				return '';
			}

			return this.mapBlock.imageUrl;
		},
	},
	template: `
		<BaseBlock
			:message="message"
			:block="block"
			:dialogId="dialogId"
		>
			<div class="bx-im-message-block-map__container">
				<div class="bx-im-message-block-map__image-container">
					<img :src="imageSource" :alt="mapBlock.text" class="bx-im-message-block-map__image">
					<div
						v-if="hasStatus"
						:title="mapBlock.status"
						class="bx-im-message-block-map__location-status --ellipsis"
					>
						{{ mapBlock.status }}
					</div>
				</div>
				<div v-if="hasText" class="bx-im-message-block-map__location">
					<BIcon :name="OutlineIcons.LOCATION" class="bx-im-message-block-map__location-icon" />
					<div
						:title="mapBlock.text" 
						class="bx-im-message-block-map__location-text --line-clamp-2"
					>
						{{ mapBlock.text }}
					</div>
				</div>
			</div>
		</BaseBlock>
	`,
});
