import { defineComponent, type PropType } from 'ui.vue3';

import { type LineDividerBlockType } from 'im.v2.const';

import { BaseBlock } from '../base/base';

import './line-divider.css';

// @vue/component
export const LineDivider = defineComponent({
	name: 'LineDivider',
	components: { BaseBlock },
	props: {
		message: {
			type: Object,
			required: true,
		},
		block: {
			type: Object as PropType<LineDividerBlockType>,
			required: true,
		},
		dialogId: {
			type: String,
			required: true,
		},
	},
	computed: {
		lineDividerBlock(): LineDividerBlockType
		{
			return this.block;
		},
	},
	template: `
		<BaseBlock
			:message="message"
			:block="lineDividerBlock"
			:dialogId="dialogId"
		>
			<div class="bx-im-message-block-line-divider__container">
				<div class="bx-im-message-block-line-divider__line"></div>
			</div>
		</BaseBlock>
	`,
});
